export interface ApprovalCardProps{ticketNumber:number;ticketTitle:string;toolName:string;/** Pretty-printed JSON of the tool input */toolInput:string;risk?:"LOW"|"MEDIUM"|"HIGH";requestedAt?:string;agentName?:string;/** How long the run has been paused, e.g. "18m" */blockedFor?:string;/** One line on what happens if this is approved */impact?:string;/** Optional before/after preview: [{op:"-"|"+",text}] */diff?:Array<{op:"+"|"-"|" ";text:string}>;/** HIGH risk is admin-only; false disables the buttons */canDecide?:boolean;onApprove?:()=>void;onReject?:()=>void}
